423			t.Fatalf("pageSize 100: %d %s", rec.Code, rec.Body.String())
424		}
425	}
426	
427	func TestPersistsAcrossReopen(t *testing.T) {
428		dir := t.TempDir()
429		path := filepath.Join(dir, "service.db")
430	
431		st, err := store.Open(path)
432		if err != nil {
433			t.Fatalf("open: %v", err)
434		}
435		router1 := NewRouter(st)
436		rec := postSBOM(t, router1, `{"artifact":"app","version":"1","components":[{"coordinate":"c","license":"L","dependencies":[]}]}`)
437		var first model.SBOM
438		decodeBody(t, rec, &first)
439		if err := st.Close(); err != nil {
440			t.Fatalf("close: %v", err)
441		}
442	
443		st2, err := store.Open(path)
444		if err != nil {
445			t.Fatalf("reopen: %v", err)
446		}
447		defer st2.Close()
448		router2 := NewRouter(st2)
449	
450		// Same manifest after reopen: same id, 201.
451		rec = postSBOM(t, router2, `{"artifact":"app","version":"1","components":[{"coordinate":"c","license":"L","dependencies":[]}]}`)
452		if rec.Code != http.StatusCreated {
453			t.Fatalf("re-register after reopen: %d %s", rec.Code, rec.Body.String())
454		}
455		var again model.SBOM
456		decodeBody(t, rec, &again)
457		if again.ID != first.ID {
458			t.Fatalf("id after reopen = %d, want %d", again.ID, first.ID)
459		}
460	
461		// Changed content after reopen still conflicts.
462		expectError(t, postSBOM(t, router2,
463			`{"artifact":"app","version":"1","components":[{"coordinate":"c","license":"X","dependencies":[]}]}`),
464			http.StatusConflict, "SbomConflictError")
465	
466		// Query sees the persisted record.
467		rec = getSBOMs(t, router2, "/sboms?artifact=app")
468		var page listResponse
469		decodeBody(t, rec, &page)
470		if page.Total != 1 || page.Items[0].ID != first.ID {
471			t.Fatalf("list after reopen = %+v", page)
472		}
473	}
474	
475	func TestConcurrentIdenticalRegistersShareOneRecord(t *testing.T) {
476		router, _ := newTestRouter(t)
477		body := `{"artifact":"race","version":"1","components":[
478			{"coordinate":"a","license":"L","dependencies":["b"]},
479			{"coordinate":"b","license":"L","dependencies":[]}
480		]}`
481		const n = 8
482		var wg sync.WaitGroup
483		ids := make(chan int64, n)
484		statuses := make(chan int, n)
485		for i := 0; i < n; i++ {
486			wg.Add(1)
487			go func() {
488				defer wg.Done()
489				rec := postSBOM(t, router, body)
490				statuses <- rec.Code
491				if rec.Code == http.StatusCreated {
492					var got model.SBOM
493					json.Unmarshal(rec.Body.Bytes(), &got)
494					ids <- got.ID
495				}
496			}()
497		}
498		wg.Wait()
499		close(ids)
500		close(statuses)
501	
502		first := int64(-1)
503		for status := range statuses {
504			if status != http.StatusCreated {
505				t.Fatalf("concurrent register status = %d, want 201", status)
506			}
507		}
508		count := 0
509		for id := range ids {
510			if first == -1 {
511				first = id
512			} else if id != first {
513				t.Fatalf("concurrent registers produced ids %d and %d", first, id)
514			}
515			count++
516		}
517		if count != n {
518			t.Fatalf("created responses = %d, want %d", count, n)
519		}
520	}
521	
522	func TestStorageFailureMapsTo503(t *testing.T) {
523		st, err := store.Open(filepath.Join(t.TempDir(), "service.db"))
524		if err != nil {
525			t.Fatalf("open: %v", err)
526		}
527		router := NewRouter(st)
528		if err := st.Close(); err != nil {
529			t.Fatalf("close: %v", err)
530		}
531	
532		expectError(t, postSBOM(t, router, `{"artifact":"a","version":"1","components":[]}`),
533			http.StatusServiceUnavailable, "storage_unavailable")
534		expectError(t, getSBOMs(t, router, "/sboms?artifact=a"),
535			http.StatusServiceUnavailable, "storage_unavailable")
536	}
537	
538	func assertSBOMEqual(t *testing.T, got, want *model.SBOM) {
539		t.Helper()
540		if got.Artifact != want.Artifact || got.Version != want.Version {
541			t.Fatalf("artifact/version = %q/%q, want %q/%q", got.Artifact, got.Version, want.Artifact, want.Version)
542		}
543		if len(got.Components) != len(want.Components) {
544			t.Fatalf("components len = %d, want %d", len(got.Components), len(want.Components))
545		}
546		for i := range want.Components {
547			g, w := got.Components[i], want.Components[i]
548			if g.Coordinate != w.Coordinate || g.License != w.License {
549				t.Fatalf("component %d = %+v, want %+v", i, g, w)
550			}
551			if len(g.Dependencies) != len(w.Dependencies) {
552				t.Fatalf("deps of %s = %v, want %v", g.Coordinate, g.Dependencies, w.Dependencies)
553			}
554			for j := range w.Dependencies {
555				if g.Dependencies[j] != w.Dependencies[j] {
556					t.Fatalf("deps of %s = %v, want %v", g.Coordinate, g.Dependencies, w.Dependencies)
557				}
558			}
559		}
560	}
